 .bgTextline__area {
  width: 100%;
  height: auto;
  position: relative;
  font-size: min(3vw, 16px);
}

 .bgTextline__area img {
  width: 100%;
  height: auto;
}

 .bgTextline__box {
  width: 100%;
  position: absolute;
  left: 0;
  top: 28%;
}

 .bgTextline__box>div {
  margin-bottom: 0.3em;
}

 .bgTextline__box p {
  background: linear-gradient(120deg, #cc208e 0%, #6713d2 100%);
  color: #fff;
  font-weight: bold;
  padding: 0.2em 0.8em;
  display: inline;
  font-size: 1.9em;
}

 .ttl_anim {
  position: relative;
  overflow: hidden;
  opacity: 0;
}

 .is-active .ttl_anim {
  animation: ttl_anim 1s forwards;
}

 .ttl_anim_line::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  background-color: #fff;
  top: 0;
  left: 0;
}

 .is-active .ttl_anim_line::before {
  animation: line 1s forwards ease-in-out;
}

 .ttl_anim .ttl_anim_txt {
  opacity: 0;
}

 .is-active .ttl_anim .ttl_anim_txt {
  animation: ttl_anim_txt 1s forwards;
  animation-delay: 0.5s;
}

@keyframes ttl_anim {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes line {
  0% {
    transform-origin: left;
    transform: scaleX(0);
  }

  50% {
    transform-origin: left;
    transform: scaleX(1);
  }

  50.001% {
    transform-origin: right;
  }

  100% {
    transform-origin: right;
    transform: scaleX(0);
  }
}

@keyframes ttl_anim_txt {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

 .htmlValue .ttl_anim,
 .htmlValue .ttl_anim .ttl_anim_txt {
  opacity: 1;
}

 .htmlValue .ttl_anim_line::before {
  background: transparent;
}

.reflect-body {
  font-size: 16px;
  text-align: center;
  font-family: serif;
}

.reflect-title {
  font-size: 2.8em;
  color: #72d0df;
  line-height: 1;
  mask-image: -webkit-linear-gradient(rgba(0, 0, 0, .35), rgba(0, 0, 0, 0.8) 30%, rgba(0, 0, 0, 1))
}

.reflect-title::after {
  content: attr(title);
  display: block;
  transform: rotateX(180deg);
  clip-path: polygon(0 50%, 100% 50%, 100% 100%, 0 100%);
  background-image: linear-gradient(0deg, currentColor, rgba(237, 249, 251, 0.13) 55%, rgba(255, 255, 255, 0));
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.marker {
  background: linear-gradient(transparent 50%, #ffdc7b 50%);
  display: inline;
  background-repeat: no-repeat;
  background-size: 0% 100%;
  transition: background-size 1.5s;
}

.marker.active {
  background-size: 100% 100%;
}

.highlight {
  font-size: 120%;
  font-weight: bold;
  color: #ff0000;
}

.swing-anime {
  display: inline-block;
  margin: 0 0.4em;
  animation: swing-anime 5s infinite linear alternate;
}

@keyframes swing-anime {
  0% {
    transform: translate(0, 5px) rotate(-5deg) scale(0.9);
  }

  50% {
    transform: translate(0, -5px) rotate(0deg) scale(1.1);
  }

  100% {
    transform: translate(0, 5px)rotate(5deg) scale(0.9);
  }
}

.decoration-text {
  width: fit-content;
  font-size: 16px;
  display: inline-block;
  letter-spacing: calc(var(--font-size) * 0.01 + .5em);
  line-height: 1.0;
  font-feature-settings: 'palt';
  font-family: YuMincho, "Hiragino Mincho ProN", serif;
}

.text-item {
  display: inline-block;
  position: relative;
  font-size: var(--font-size);
  font-weight: 900;
  filter: drop-shadow(1px 3px 2px rgba(0, 0, 0, 0.5));
  animation-name: text-item;
  animation-duration: calc(var(--totalIndex) * var(--base-ms));
  animation-iteration-count: infinite;
  animation-timing-function: linear;
  animation-delay: calc((var(--index) - 1) * var(--base-ms));
}



/*  */
.text-item span {
  position: relative;
  color: transparent;
  background-image: linear-gradient(0deg, #FEE37B, rgba(255, 255, 255, 1) 50%, #ff0);
  background-clip: text;
  -webkit-text-stroke: .008em #000;
  z-index: 2;
}

.text-item::before {
  -webkit-text-stroke: calc(((var(--font-size) * 0.01) + 5px)) #D4494F;
  z-index: 1;
}

.text-item::after {
  -webkit-text-stroke: calc((var(--font-size) * 0.01) + 12px) #ffffff;
  z-index: 0;
}

.text-item::before,
.text-item::after {
  content: attr(data-text);
  width: 100%;
  color: #fff;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

@keyframes text-item {
  0%,
  100% {
    transform: scale(1);
  }
  15% {
    transform: scale(1);
  }
  10% {
    transform: scale(1.2);
  }
}

