.hilight-text {
  font-size: 16px;
  width: fit-content;
  position: relative;
  overflow: hidden;
}

.hilight-text.center {
  margin: auto;
}

.hilight-text .bgcolor,
.hilight-text::after {
  content: "";
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
  transition: 1s;
}

.hilight-text .bgcolor {
  background-color: currentcolor;
  z-index: 0;
  translate: -101% 0;
}

.hilight-text>*:not(.bgcolor) {
  width: fit-content;
  padding: 0.25em 0.5em;
  position: relative;
  z-index: 1;
  box-sizing: border-box;
}

.hilight-text[data-animation=slide-in-out]::after {
  background-color: #FFF;
  z-index: 2;
  translate: -100% 0;
}

.hilight-text[data-animation=slide-in-out]>*:not(.bgcolor) {
  opacity: 0;
}

.hilight-text[data-animation=slide-in-text]>*:not(.bgcolor) {
  translate: -101% 0;
}

.hilight-text.is-hilighted {
  opacity: 1 !important;
}

.hilight-text.is-hilighted[data-animation] .bgcolor {
  animation: hilight-bg-before 0.75s 0.25s ease-out forwards;
}

.hilight-text.is-hilighted[data-animation=slide-in-out] .bgcolor {
  animation: hilight-bg-before 0.5s 0.5s ease-in-out forwards;
}

.hilight-text.is-hilighted[data-animation=slide-in-out]::after {
  animation: hilight-bg 1s ease-in-out forwards;
}

.hilight-text.is-hilighted[data-animation=slide-in-out]>* {
  animation: hilight-text 0s 0.5s ease-in-out forwards;
}

.hilight-text.is-hilighted[data-animation=slide-in-text] .bgcolor {
  animation: hilight-bg-before 1s 0s ease-out forwards;
}

.hilight-text.is-hilighted[data-animation=slide-in-text]>*:not(.bgcolor) {
  animation: hilight-bg-before 0.5s 0.5s ease-in-out forwards;
}

.image img {
  width: 100%;
}

@media (max-width: 500px) {
  .hilight-text {
    font-size: 3.3vw;
  }
}

.hilight-text.init>*:not(.bgcolor) {
  opacity: 1 !important;
  translate: 0 0 !important;
}

.hilight-text.init:after {
  opacity: 0 !important;
}

@keyframes hilight-text {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
