  /*下線の色は()内のカラーコード2箇所を変更。
  下線の太さ変更は下記4px部分を変更して、下の.underline-animation.isActiveの4pxも同じ数値に変更*/
  background: linear-gradient(#e25ad7, #e25ad7) 0 100%/0 4px no-repeat;
  /*アニメーションの速度 1s=1秒*/
  transition: background 2s;
  /*行間の高さ*/
  line-height: 1.8;
  /*文字の太さ。太字はbold、標準の太さはnormal*/
  font-weight: normal;
  text-decoration: none;
}

