  background-image: -webkit-radial-gradient(0.5em at center, rgba(0, 0, 0, 1) 0%, rgba(0, 0, 0, 1) 20%, rgba(0, 0, 0, 0) 21%, rgba(0, 0, 0, 0) 100%);
