span {
  /*圏点の色変更は下記を変更*/
  text-emphasis-color: #db535a;
  -webkit-text-emphasis-color: #db535a;
  /*圏点の位置を文字の下にする場合は下記 over right を under right に変更*/
  text-emphasis-position: over right;
  -webkit-text-emphasis-position: over right;
}

span.dot {
  /*dot = ドット*/
  text-emphasis-style: dot;
  -webkit-text-emphasis-style: dot;
}

span.circle {
  /*circle = 丸
 　　　　open 追記で塗りなし。例: open circle*/
  text-emphasis-style: circle;
  -webkit-text-emphasis-style: circle;
}

span.triangle {
  /*triangle = 三角   
 　　　　open 追記で塗りなし。例: open triangle*/
  text-emphasis-style: triangle;
  -webkit-text-emphasis-style: triangle;
}

span.double-circle {
  /*double-circle = 二重丸
 　　　　open 追記で塗りなし。例: open double-circle*/
  text-emphasis-style: double-circle;
  -webkit-text-emphasis-style: double-circle;
}

span.sesame {
  /*sesame = ごま
 　　　　open 追記で塗りなし。例: open sesame*/
  text-emphasis-style: sesame;
  -webkit-text-emphasis-style: sesame;
}

span.emoji {
  /*絵文字一覧はこちら→　https://lets-emoji.com/emojilist/
