.marker {
  background-size: 100% 40%;
  background-repeat: no-repeat;
  background-position: bottom;
  border-radius: 2em 0 1em 0;
}

.line-red {
  background-image: linear-gradient(100deg,
      rgba(244, 178, 186, 0.1),
      rgba(244, 178, 186, 1) 5%,
      rgba(244, 178, 186, 0.2));
}

.line-yellow {
  background-image: linear-gradient(100deg,
      rgba(255, 234, 154, 0.1),
      rgba(255, 234, 154, 1) 5%,
      rgba(255, 234, 154, 0.5));
}

.line-green {
  background-image: linear-gradient(100deg,
      rgba(198, 218, 135, 0.1),
      rgba(198, 218, 135, 1) 5%,
      rgba(198, 218, 135, 0.2));
}

.line-blue {
  background-image: linear-gradient(100deg,
      rgba(189, 209, 234, 0.1),
      rgba(189, 209, 234, 1) 5%,
      rgba(189, 209, 234, 0.2));
}

.marker-animation.is-active {
  background-position: -100% bottom;
}

.marker-animation {
  background-image: linear-gradient(to right, transparent 50%, #ffff00 50%);
  background-size: 200% 0.6em;
  transition: all 2s ease;
  background-position: 0 bottom;
  background-repeat: repeat-x;
}

.undermarker-blue {
  background: linear-gradient(transparent 60%, #cce5ff 0%);
}

.undermarker-yellow {
  background: linear-gradient(transparent 60%, #FEFFBC 0%);
}

.undermarker-pink {
  background: linear-gradient(transparent 60%, #FFDFEF 0%);
}
